function parseThresholds(thresholdStrings?: string[]): { parsed: Record<string, number>; error?: string } {
  const thresholds: Record<string, number> = {};

  if (!thresholdStrings || thresholdStrings.length === 0) {
    return { parsed: thresholds };
  }

  for (const str of thresholdStrings) {
    const match = str.match(/^([a-z_]+)=(.+)$/);
    if (!match) {
      return {
        parsed: {},
        error: `Malformed threshold: ${str}. Expected format: <metric>=<number> (e.g., exact_match=0.9)`
      };
    }

    const [, metricId, valueStr] = match;
    const value = parseFloat(valueStr);
    if (Number.isNaN(value) || value < 0 || value > 1) {
      return {
        parsed: {},
        error: `Invalid threshold value: ${str}. Threshold must be a number between 0 and 1.`
      };
    }

    thresholds[metricId] = value;
  }

  return { parsed: thresholds };
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  const { parsed: thresholds, error: parseError } = parseThresholds(options.threshold);
  if (parseError) {
    log.error(parseError);
    process.exitCode = 2;
    return;
  }

  const validation = (Eval.validateThresholds as unknown as (config: unknown) => any)(thresholds);
  if (!validation.valid) {
    validation.errors.forEach((err: any) => {
      console.error(`  - ${err.message}`);
    });
    process.exitCode = 2;
    return;
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });
  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: Object.keys(thresholds).length > 0 ? thresholds : undefined
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (report.passed === false) {
    process.exitCode = 1;
  }
}

