import fs from 'fs';
import path from 'path';

import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

const getMetricIds = () => DEFAULT_METRICS.map((metric) => {
  if (typeof metric === 'function') return metric.name || 'unknown';
  if (metric && typeof metric.id === 'string') return metric.id;
  return 'unknown';
});

export function validateThresholds(thresholds = {}) {
  const errors = [];
  if (!thresholds || Object.keys(thresholds).length === 0) {
    return { valid: true, errors };
  }

  const validMetricIds = new Set();
  DEFAULT_METRICS.forEach((metric) => {
    if (typeof metric === 'function') {
      validMetricIds.add(metric.name);
    } else if (metric && typeof metric.id === 'string') {
      validMetricIds.add(metric.id);
    }
  });

  Object.entries(thresholds).forEach(([metricId, min]) => {
    if (!validMetricIds.has(metricId)) {
      errors.push({
        metric: metricId,
        message: `Unknown metric: ${metricId}. Valid metrics: ${Array.from(validMetricIds).join(', ')}.`
      });
    }
    if (typeof min !== 'number' || min < 0 || min > 1) {
      errors.push({
        metric: metricId,
        message: `Invalid threshold: ${metricId}=${min}. Threshold must be a number between 0 and 1.`
      });
    }
  });

  return { valid: errors.length === 0, errors };
}

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);

