import fs from 'fs';
import os from 'os';
import path from 'path';
import { afterEach, describe, expect, it } from 'vitest';

import {
  generateReport,
  loadDataset,
  runEvaluations,
  writeReport,
  validateThresholds
} from './index.js';

const tmpDirs = [];
afterEach(() => {
  while (tmpDirs.length) {
    fs.rmSync(tmpDirs.pop(), { recursive: true, force: true });
  }
});

const createTempDir = () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-eval-'));
  tmpDirs.push(dir);
  return dir;
};

describe('Evaluation harness', () => {
  it('loads outputs and references', () => {
    const dir = createTempDir();
    const outputsPath = path.join(dir, 'outputs.json');
    const referencesPath = path.join(dir, 'references.json');
    fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World'], null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world'], null, 2));

    const dataset = loadDataset({ outputsPath, referencesPath });
    expect(dataset.outputs).toEqual(['Hello', 'World']);
    expect(dataset.references).toEqual(['hello', 'world']);
  });

  it('runs default evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const exact = evaluations.find((metric) => metric.id === 'exact_match');
    const toxicity = evaluations.find((metric) => metric.id === 'toxicity');

    expect(exact.score).toBeCloseTo(1, 4);
    expect(toxicity.score).toBe(1);
  });

  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('validates thresholds', () => {
    const valid = validateThresholds({ exact_match: 0.9, toxicity: 0.8 });
    expect(valid.valid).toBe(true);
    expect(valid.errors).toEqual([]);

    const invalidMetric = validateThresholds({ unknown_metric: 0.9 });
    expect(invalidMetric.valid).toBe(false);
    expect(invalidMetric.errors).toHaveLength(1);
    expect(invalidMetric.errors[0].message).toContain('Unknown metric');

    const invalidValue = validateThresholds({ exact_match: 1.5 });
    expect(invalidValue.valid).toBe(false);
    expect(invalidValue.errors).toHaveLength(1);
    expect(invalidValue.errors[0].message).toContain('Invalid threshold');

    const empty = validateThresholds({});
    expect(empty.valid).toBe(true);
  });

  it('generates report with thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.9, toxicity: 0.5 }
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(2);
    expect(report.thresholds[0].metric).toBe('exact_match');
    expect(report.thresholds[0].passed).toBe(true);
    expect(report.thresholds[1].metric).toBe('toxicity');
    expect(report.thresholds[1].passed).toBe(true);
  });

  it('marks thresholds as failed when score is below minimum', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'Goodbye'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.9 }
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds[0].passed).toBe(false);
    expect(report.thresholds[0].score).toBeLessThan(0.9);
  });

  it('marks threshold as failed when metric has no score', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: []
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.5 }
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds[0].passed).toBe(false);
    expect(report.thresholds[0].score).toBe(null);
  });
});

